export function validateOrder(order) {
  if (!order || typeof order !== 'object' || !Array.isArray(order.lines) || order.lines.length === 0) throw new Error('INVALID_ORDER');
  for (const line of order.lines) {
    if (!line || typeof line !== 'object') throw new Error('INVALID_ORDER');
    if (typeof line.sku !== 'string') throw new Error('INVALID_ORDER');
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) throw new Error('INVALID_ORDER');
  }
  return order;
}
```
Note: `{ sku: 'A' }` has no lines array → throws. `{ lines: [] }` → throws. `{ lines: [null] }` → throws. `{ lines: [{sku:1, quantity:1}] }` → throws. quantity 0, -1, 1.5, '2' → throws. Good. No mutation. Returns order.

