import { validateOrder } from './contract.mjs';
const prices = { A: 125, B: 300 };
export function quote(order) {
  validateOrder(order);
  const items = [];
  let totalCents = 0;
  for (const line of order.lines) {
    if (!Object.prototype.hasOwnProperty.call(prices, line.sku)) throw new Error('UNKNOWN_SKU');
    const lineCents = prices[line.sku] * line.quantity;
    items.push({ sku: line.sku, quantity: line.quantity, lineCents });
    totalCents += lineCents;
  }
  return { items, totalCents };
}
```
Note "目录仅 A/B，不能把对象继承属性当成目录条目" → use hasOwnProperty or Object.hasOwn. Node 22 supports Object.hasOwn. I'll use Object.hasOwn for clarity... but style? Either fine. Use Object.hasOwn(prices, line.sku).

